async function handleEvent(event) {
  if (event.type !== "message" || event.message.type !== "text") return;
  const userId = event.source.userId;

  // 1. Show the loading dots (1-on-1 chats only, 5 to 60 seconds).
  if (event.source.type === "user") {
    await client.showLoadingAnimation({ chatId: userId, loadingSeconds: 20 });
  }

  // 2. Keep a short history per user.
  const turns = history.get(userId) ?? [];
  turns.push({ role: "user", content: event.message.text });

  // 3. Call your model. askLLM is your own function (OpenAI, Gemini, Typhoon, etc.).
  const answer = await askLLM(turns.slice(-10));
  turns.push({ role: "assistant", content: answer });
  history.set(userId, turns.slice(-10));

  // 4. Answer once with the free reply token.
  await client.replyMessage({
    replyToken: event.replyToken,
    messages: [{ type: "text", text: answer }],
  });
}

